create table if not exists classroom_rooms (id uuid primary key default gen_random_uuid(), class_id uuid, teacher_id uuid, status text not null default 'scheduled', started_at timestamptz, ended_at timestamptz, max_students int not null default 50 check (max_students <= 50), max_cameras int not null default 10 check (max_cameras <= 10), created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table classroom_rooms enable row level security; create index if not exists idx_classroom_rooms_class_id on classroom_rooms(class_id); create index if not exists idx_classroom_rooms_teacher_id on classroom_rooms(teacher_id);
